def test_eda_association_views() -> None:
    views = task_views(_task("association", learning_type="unsupervised"))
    assert views == ("item_frequency", "basket_size")
    assert "item_frequency" in eda_plan(_task("association", learning_type="unsupervised"))


def test_eda_samples_large_data() -> None:
    small = pd.DataFrame({"x": range(50)})
    assert sample_frame_for_eda(small) is small

    large = pd.DataFrame({"x": range(EDA_MAX_ROWS * 3)})
    first = sample_frame_for_eda(large, seed=7)
    second = sample_frame_for_eda(large, seed=7)
    assert len(first) == EDA_MAX_ROWS
    assert first.index.equals(second.index)

    frame = pd.DataFrame({"cat": ["a"] * 3 + ["b"] * 3, "n": range(6)})
    assert categorical_cardinalities(frame) == {"cat": 2}
